(1, '50k Salary Survival Guide', '50k-salary-survival-guide', 'salary_based', 50000, 0, NULL, '{\"salary\":50000,\"family_size\":3,\"source\":\"ai\",\"generated_at\":\"2026-03-28T06:06:43+00:00\",\"categories\":[{\"category\":\"Atta\",\"amount\":6300,\"percentage\":12.5},{\"category\":\"Ghee\",\"amount\":3800,\"percentage\":7.5},{\"category\":\"Sugar\",\"amount\":2500,\"percentage\":5},{\"category\":\"Electricity\",\"amount\":7500,\"percentage\":15},{\"category\":\"Gas\",\"amount\":5000,\"percentage\":10},{\"category\":\"School Fees\",\"amount\":24900,\"percentage\":50}],\"saving_tips\":[\"1. Try to reduce electricity usage by using natural light during the day and turning off lights and appliances when not in use.\",\"2. Consider buying in bulk or finding cheaper suppliers for items like Atta, Ghee, and Sugar.\",\"3. Look for ways to reduce gas usage, such as using a pressure cooker to cook food quickly and efficiently.\"]}', '2026-03-27 11:24:35', '2026-03-28 06:06:43'),
(2, '100k Family Budget', '100k-family-budget', 'family', 100000, 1, 1499, '{\"salary\":100000,\"family_size\":5,\"source\":\"ai\",\"generated_at\":\"2026-03-28T06:04:34+00:00\",\"categories\":[{\"category\":\"Atta\",\"amount\":10000,\"percentage\":10},{\"category\":\"Ghee\",\"amount\":6000,\"percentage\":6},{\"category\":\"Sugar\",\"amount\":4000,\"percentage\":4},{\"category\":\"Electricity (Protected Slab Estimate)\",\"amount\":12000,\"percentage\":12},{\"category\":\"Gas\",\"amount\":8000,\"percentage\":8},{\"category\":\"School Fees (If Family Size > 2)\",\"amount\":60000,\"percentage\":60}],\"saving_tips\":[\"Tip 1: Try to negotiate a group discount for school fees.\",\"Tip 2: Consider switching to a cheaper electricity supplier or plan.\",\"Tip 3: Reduce your consumption of ghee and sugar by using them sparingly.\"]}', '2026-03-27 11:24:35', '2026-03-28 06:04:34'),
(3, 'Student Budget', 'student-budget', 'student', 25000, 0, NULL, '{\"salary\":25000,\"family_size\":1,\"source\":\"ai\",\"generated_at\":\"2026-03-28T06:11:02+00:00\",\"categories\":[{\"category\":\"Atta\",\"amount\":5400,\"percentage\":21.43},{\"category\":\"Ghee\",\"amount\":3600,\"percentage\":14.29},{\"category\":\"Sugar\",\"amount\":1800,\"percentage\":7.14},{\"category\":\"Electricity\",\"amount\":8900,\"percentage\":35.71},{\"category\":\"Gas\",\"amount\":5400,\"percentage\":21.43},{\"category\":\"School Fees\",\"amount\":-100,\"percentage\":0}],\"saving_tips\":[\"Tip 1: Try to reduce electricity usage by using natural light during the day and turning off lights and appliances when not in use.\",\"Tip 2: Consider buying in bulk for items like Atta, Ghee, and Sugar to take advantage of discounts.\",\"Tip 3: Look for ways to cut back on discretionary spending, such as eating out or entertainment, to save extra money.\"]}', '2026-03-27 11:24:35', '2026-03-28 06:11:02'),
(4, 'Joint Family Budget', 'joint-family-budget', 'joint_family', 150000, 1, 2499, '{\"salary\":150000,\"family_size\":8,\"source\":\"ai\",\"generated_at\":\"2026-03-28T06:08:56+00:00\",\"categories\":[{\"category\":\"Atta\",\"amount\":21100,\"percentage\":14.05},{\"category\":\"Ghee\",\"amount\":13200,\"percentage\":8.78},{\"category\":\"Sugar\",\"amount\":7900,\"percentage\":5.26},{\"category\":\"Electricity (Protected Slab Estimate)\",\"amount\":15800,\"percentage\":10.52},{\"category\":\"Gas\",\"amount\":13200,\"percentage\":8.78},{\"category\":\"School Fees (If Family Size > 2)\",\"amount\":78800,\"percentage\":52.6}],\"saving_tips\":[\"Consider buying groceries in bulk to take advantage of discounts.\",\"Try to reduce electricity usage by turning off lights and appliances when not in use.\",\"Consider carpooling or using public transportation to save on fuel costs.\"]}', '2026-03-27 11:24:35', '2026-03-28 06:08:56');
